type RegionInput = Omit<Region, "hemisphere" | "latitudeBelt" | "sources" | "subregions">;

function createRegion(region: RegionInput): Region {
  return {
    ...region,
    hemisphere: getHemisphere(region.latitude),
    latitudeBelt: getLatitudeBelt(region.latitude),
    subregions: createSubregions(region),
    sources: [geographicSource, editorialSource],
  };
}

function createSubregions(region: RegionInput): Subregion[] {
  return (subregionsById[region.id] ?? []).map((name) => {
    const profile = subregionProfiles[`${region.id}/${name.toLowerCase().replaceAll(" ", "-")}`];

    return profile
      ? { name, ...profile, hasDedicatedProfile: true }
      : {
          name,
          overview: `${name} is a named place within ${region.name}. A dedicated local profile is still being researched.`,
          geographicFactors: region.geographicFactors,
          grapes: region.grapes,
          styles: region.styles,
          hasDedicatedProfile: false,
        };
  });
}

